insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_kingdoms_worst_day_q01_fenn_done","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q01_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q02_will_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q02_will_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q03_painter_done","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q03_painter_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_guide_start","speaker_external_id":"Mountain Guide","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_maya_done","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_professor_done","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_professor_start","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":0,"content":"מצוין. עכשיו ברור אילו דברים הגיעו ליריד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":1,"content":"ויל Blacksmith מכין את הדוכן, אבל ההוראות שלו כבר לא ברורות.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":2,"content":"לכו אליו ותשאלו איך אפשר לעזור לו.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":0,"content":"היום נפתח היריד לילדים ליד שער הממלכה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":1,"content":"הגיעו לשם כמה דברים, אבל השמות שלהם נמחקו מהפתקים.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":2,"content":"שם עצם הוא מילה שנותנת שם לאדם, לחיה, למקום או לדבר.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":3,"content":"עזרו לי לזהות את הדברים, כדי שאוכל להכין את היריד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":0,"content":"תודה. עכשיו אני יודע איך להמשיך בבנייה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":1,"content":"הציירת Painter מכינה את השלטים ליריד, אבל קשה לה לתאר אותם.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":2,"content":"לכו אליה ותשאלו איך אפשר לעזור לה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":0,"content":"אני בונה את הדוכן, אבל פתקי העבודה התבלבלו.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":1,"content":"פועל הוא מילה שמספרת מה מישהו עושה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":2,"content":"עזרו לי להבין את הפעולות, כדי שאספיק לסיים בזמן.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_done","locale":"he","line_order":0,"content":"נהדר. עכשיו השלטים ברורים וקל להבין אותם.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_done","locale":"he","line_order":1,"content":"פרופסור קרייזי Professor Crazy מכין את ההודעה שתשמע בתחילת היריד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_done","locale":"he","line_order":2,"content":"לכו אליו ועזרו לו להכין אותה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":0,"content":"אני מכינה שלטים צבעוניים ליריד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":1,"content":"שם תואר הוא מילה שמתארת אדם, חיה, מקום או דבר.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":2,"content":"עזרו לי לבחור תיאורים ברורים, כדי שהילדים ימצאו כל דוכן.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":0,"content":"האורחים כבר מתקרבים, והם מחכים להודעה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":1,"content":"נעביר אותה בקול ברור, כדי שכולם יידעו שהיריד פתוח.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":2,"content":"אחר כך חזרו אל המורה מאיה Teacher Maya וספרו לה שהכול מוכן.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":0,"content":"עשיתם עבודה נהדרת. היריד יכול להתחיל.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":1,"content":"שמות, פעולות ותיאורים עזרו לכולם להבין את ההודעה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"en","line_order":2,"content":"Words make sentences, and sentences help people understand.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":3,"content":"מילים יוצרות משפטים, ומשפטים עוזרים לאנשים להבין.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":4,"content":"כל הכבוד! הנה 50 מטבעות בשבילכם.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_done","locale":"he","line_order":0,"content":"ההודעה מוכנה. עכשיו כולם יוכלו להבין אותה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_done","locale":"he","line_order":1,"content":"מדריך ההרים Mountain Guide יעביר אותה בקול לאורחים שבדרך.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_done","locale":"he","line_order":2,"content":"לכו אליו כדי שהיריד יוכל להתחיל.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":0,"content":"אני מכין הודעה לאורחים, אבל המילים התערבבו.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":1,"content":"הודעה ברורה צריכה שמות של דברים, פעולות ותיאורים.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":2,"content":"עזרו לי לסדר אותה, כדי שכל הילדים יבינו לאן ללכת.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
